const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf8');

// Search for user_8e79d830
const idx = str.indexOf('user_8e79d830');
// Find all occurrences
let positions = [];
let searchIdx = 0;
while (true) {
  const found = str.indexOf('user_8e79d830', searchIdx);
  if (found < 0) break;
  positions.push(found);
  searchIdx = found + 1;
}
console.log('Found user_8e79d830 at positions:', positions);

// Look for user details (should be in users table)
for (const pos of positions) {
  const ctx = str.slice(Math.max(0, pos - 100), pos + 500).replace(/[^\x20-\x7E\n]/g, '|');
  console.log('\\n=== Context at', pos, '===');
  console.log(ctx);
  console.log('---');
}
